<?php

namespace App\Medicine\Repository;


use App\Medicine\Entity\MedicineGeneric;
use Doctrine\ORM\EntityRepository;

/**
 * GenericRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class MedicineGenericRepository extends EntityRepository
{
    public function checkGenericName($name){

        $generic = $this->findOneBy(['name'=>$name]);
        $em = $this->getEntityManager();
        if(empty($generic)){
            $entity = new MedicineGeneric();
            $entity->setName($name);
            $em->persist($entity);
            $em->flush();
            return $entity;
        }else{
          return $generic;
        }
    }
}
